#!/usr/bin/env node
// bundle copy generated by scripts/sync-assets.mjs: main-guard keyed on CCO_HOOK_MAIN (see resources/entry/cco-hook-bundle.mjs)
/**
 * preToolUse hook on every tool (the script decides; Task is handled by cco-task-guard).
 *
 * Makes routing deterministic and keeps the chat model's own spend small:
 *
 *  Router mode (chat model is expensive relative to the FAST tier, or enforcement=always):
 *    - before delegation: every tool except Task is denied → the chat model's first action is the Task call
 *    - after delegation: every tool except Task is denied (cascade only) → the chat model relays the result
 *      instead of re-reading files and re-running checks on the expensive model
 *  Lenient mode (chat model is already cheap):
 *    - only high-risk work is redirected (to a stronger tier); reads are always allowed
 *
 * Subagent conversations (no session file), background agents, [cco:off], and the escape hatch
 * (after N denials) are always allowed. Fail-open on any error.
 */
import {
  readStdin,
  safeJsonParse,
  workspaceFromPayload,
  workspacePaths,
  readJsonSafe,
  hookLog,
  emit,
  asNumber,
  TIERS,
  isEnabled, isMain, applyScopeArgs, agentForTier, windowLacksAgents } from "./lib/common.mjs";
applyScopeArgs();
import { loadConfig } from "./lib/config.mjs";
import { modelLimitedUntil } from "./lib/state.mjs";
import { tierLabel, modelLabel } from "./lib/labels.mjs";
import { loadPricing, resolveModelPrice, blendedRatePerMillion } from "./lib/pricing.mjs";
import { heuristicScores, decideTier, parseOverride, isQuestionLike, isTinyTask } from "./lib/scorer.mjs";
import { loadSession, saveSession, userPromptFromTranscript, guessTranscriptPath, refineSessionModel, syncTurnFromTranscript, userPromptFromTranscriptTurn } from "./lib/session.mjs";
import { agentNames, readWorkspaceAgentModel, agentNamesForWindow } from "./lib/agents.mjs";

const DEFAULT_WORK_TOOLS = "^(Write|Edit|StrReplace|MultiEdit|Delete|Shell|Bash|NotebookEdit|ApplyPatch|CreateFile|EditFile|DeleteFile)$";

function tierModels(workspace, runtime, limitsPath = null) {
  const out = {};
  for (const tier of TIERS) {
    out[tier] = (workspace && readWorkspaceAgentModel(workspace, agentForTier(tier, workspace))) || runtime?.profiles?.[tier]?.model || "inherit";
  }
  // A tier whose model is on cooldown (refused to start a subagent: usage limit) runs on the next usable lower tier.
  if (limitsPath) {
    const order = ["fast", "balanced", "deep"];
    for (const tier of order) {
      let idx = order.indexOf(tier);
      while (idx > 0 && modelLimitedUntil(limitsPath, out[order[idx]])) idx -= 1;
      if (order[idx] !== tier) out[tier] = out[order[idx]];
    }
  }
  return out;
}

export function isRouterMode({ session, config, pricing, models }) {
  const enforcement = config?.enforcement || {};
  const mode = String(enforcement.requireDelegation || "auto");
  if (mode === "never") {
    return { router: false, factor: null, reason: "enforcement_off" };
  }
  if (mode === "always") {
    return { router: true, factor: null, reason: "always" };
  }
  // The user picked the Fast tier's model (Settings / Choose tier models): Fast work goes there, cheaper or not.
  if (String(config?.modelOverrides?.fast || "").trim()) {
    return { router: true, factor: null, reason: "fast_model_chosen_by_user" };
  }
  const sessionModel = session?.model || null;
  const sessionPrice = sessionModel ? resolveModelPrice(sessionModel, pricing, { overrides: config?.pricing?.overrides }) : null;
  const sessionRate = blendedRatePerMillion(sessionPrice);
  const fastRate = blendedRatePerMillion(models.fast === "inherit" ? null : resolveModelPrice(models.fast, pricing, { overrides: config?.pricing?.overrides }));
  const factor = sessionRate && fastRate ? sessionRate / fastRate : null;
  const minSavings = asNumber(enforcement.minSavingsFactor, 1.3);
  return { router: Boolean(factor && factor >= minSavings), factor, reason: factor ? `session_${factor.toFixed(1)}x_fast_tier` : "no_price_signal" };
}

/**
 * Pure decision. Returns { action: "allow"|"deny", reason, tier, model, decision, phase }.
 */
export function gateDecision({ toolName, session, config, pricing, models, prompt, workspace = null }) {
  const enforcement = config?.enforcement || {};
  const mode = String(enforcement.requireDelegation || "auto");
  const tool = String(toolName || "");
  if (mode === "never") {
    return { action: "allow", reason: "enforcement_off" };
  }
  if (tool === "Task") {
    return { action: "allow", reason: "task_handled_by_guard" };
  }
  if (!session) {
    return { action: "allow", reason: "not_a_parent_conversation" };
  }
  if (session.is_background_agent) {
    return { action: "allow", reason: "background_agent" };
  }
  const meta = session.promptMeta || {};
  if (/\[cco:off\]|\[cco:direct\]/i.test(prompt || "") || meta.override === "off") {
    return { action: "allow", reason: "user_disabled" };
  }
  const maxDenials = asNumber(enforcement.maxDenialsPerConversation, 2);
  if (asNumber(session.denials, 0) >= maxDenials) {
    return { action: "allow", reason: "escape_hatch_after_denials" };
  }
  // This window's Task tool lists none of the tier subagents (set up after it opened): nothing to route to.
  if (workspace && windowLacksAgents(workspace)) {
    return { action: "allow", reason: "no_subagents_in_window" };
  }

  const delegated = Array.isArray(session.delegations) && session.delegations.some((d) => d.agent !== "fast-research" && d.agent !== "tier-verifier");
  const workTool = new RegExp(enforcement.gatedTools || DEFAULT_WORK_TOOLS, "i").test(tool);
  const readTool = /^(Read|Grep|Glob|ListDir|List|Search|Codebase|SemanticSearch|WebSearch|Fetch)/i.test(tool);
  const explored = Array.isArray(session.research) && session.research.some((r) => r.agent === "fast-research");
  const override = prompt ? parseOverride(prompt, config?.overrideTokens || {}) : meta.override || null;
  const decision = session.decision || (prompt ? decideTier({ scores: heuristicScores(prompt), override, config }) : null);
  const questionLike = prompt ? isQuestionLike(prompt) : Boolean(meta.questionLike);
  const tier = decision?.tier || null;
  const sessionModel = session.model || null;
  const routerInfo = isRouterMode({ session, config, pricing, models });
  const readBudget = asNumber(enforcement.readBudgetBeforeExplore, 3);

  if (routerInfo.router) {
    if (delegated) {
      if (enforcement.relayOnly === false) {
        return { action: "allow", reason: "already_delegated", phase: "post" };
      }
      return { action: "deny", reason: "relay_only_after_delegation", phase: "post", tier: null, model: null, decision };
    }
    if (override && override !== "auto" && models[override] === sessionModel) {
      return { action: "allow", reason: "override_matches_session_model", phase: "pre" };
    }
    const t = (override && override !== "auto" ? override : tier) || "fast";
    if (models[t] === "inherit") {
      return { action: "allow", reason: "tier_model_not_mapped", phase: "pre" };
    }
    // A FAST-tier question (explain/what/why) is cheaper to answer here with a read or two than to
    // route: a delegation costs a routing turn plus a fresh subagent session. Work tools stay gated.
    if (t === "fast" && !workTool && !(override && override !== "auto") && questionLike) {
      return { action: "allow", reason: "question_answered_directly", phase: "pre" };
    }
    // A tiny one-file edit (typo, rename, comment) is faster and about as cheap done right here.
    const tiny = prompt ? isTinyTask(prompt) : Boolean(meta.tiny);
    if (t === "fast" && !(override && override !== "auto") && tiny) {
      return { action: "allow", reason: "tiny_task_stays_in_chat", phase: "pre" };
    }
    // A subagent is a fresh session that re-caches the whole system context. Only delegate when the
    // tier model is materially cheaper than the chat model; otherwise the work stays here (no overhead).
    if (mode !== "always" && !(override && override !== "auto")) {
      const tierRate = blendedRatePerMillion(resolveModelPrice(models[t], pricing, { overrides: config?.pricing?.overrides }));
      const sessionRate = blendedRatePerMillion(resolveModelPrice(sessionModel, pricing, { overrides: config?.pricing?.overrides }));
      const minSavings = asNumber(enforcement.minSavingsFactor, 1.3);
      const qualityDriven = t === "deep" || String(decision?.guardrail || "").startsWith("risk");
      const stronger = tierRate && sessionRate && tierRate > sessionRate * 1.05;
      if (qualityDriven && stronger && models[t] !== sessionModel) {
        if (!workTool) {
          if (readTool && !explored && asNumber(session.readCount, 0) >= readBudget && models.fast !== "inherit" && models.fast !== sessionModel && !session.readNudged) {
            return { action: "deny", reason: "read_budget_use_explore", phase: "pre", tier: "explore", model: models.fast, decision };
          }
          return { action: "allow", reason: "reads_allowed_before_quality_escalation", phase: "pre" };
        }
        return { action: "deny", reason: `quality_${decision?.guardrail || "deep"}`, tier: t, model: models[t], decision, phase: "pre" };
      }
      const userChosen = Boolean(String(config?.modelOverrides?.[t] || "").trim());
      if (!userChosen && tierRate && sessionRate && sessionRate / tierRate < minSavings) {
        if (readTool && !explored && asNumber(session.readCount, 0) >= readBudget && models.fast !== "inherit" && models.fast !== sessionModel && !session.readNudged) {
          return { action: "deny", reason: "read_budget_use_explore", phase: "pre", tier: "explore", model: models.fast, decision };
        }
        return { action: "allow", reason: `tier_${t}_not_cheaper_than_session`, phase: "pre" };
      }
    }
    const reason = override && override !== "auto" ? `override_${override}` : mode === "always" ? "require_delegation_always" : `cost_${routerInfo.reason}`;
    return { action: "deny", reason, tier: t, model: models[t], decision, phase: "pre" };
  }

  // Step-level delegation: when the work rightly stays in this chat (same-model deep task, or a cheap
  // chat model), research still goes to the cheap explorer once the chat model has used its read budget.
  const bigTask = tier === "deep" || tier === "balanced";
  if (readTool && !delegated && !explored && bigTask && models.fast !== "inherit" && models.fast !== sessionModel && asNumber(session.readCount, 0) >= readBudget && !session.readNudged) {
    return { action: "deny", reason: "read_budget_use_explore", phase: "pre", tier: "explore", model: models.fast, decision };
  }
  // Lenient mode: cheap chat model. Only redirect risky/forced work, and only for work tools.
  if (delegated || !workTool) {
    return { action: "allow", reason: delegated ? "already_delegated" : "tool_not_gated", phase: delegated ? "post" : "pre" };
  }
  if (override && override !== "auto") {
    if (models[override] !== "inherit" && models[override] !== sessionModel) {
      return { action: "deny", reason: `override_${override}`, tier: override, model: models[override], decision, phase: "pre" };
    }
    return { action: "allow", reason: "override_matches_session_model", phase: "pre" };
  }
  if (tier && (tier === "deep" || decision?.guardrail?.startsWith("risk"))) {
    if (models[tier] !== "inherit" && models[tier] !== sessionModel) {
      return { action: "deny", reason: `quality_${decision.guardrail || "deep"}`, tier, model: models[tier], decision, phase: "pre" };
    }
    return { action: "allow", reason: "session_model_already_matches_tier", phase: "pre" };
  }
  return { action: "allow", reason: routerInfo.factor ? "no_savings_expected" : "no_price_signal", phase: "pre" };
}

export function denyMessage({ toolName, verdict, sessionModel, workspace = null }) {
  if (verdict.reason === "read_budget_use_explore") {
    return [
      `CCO: you have used the read budget for research on ${sessionModel || "the chat model"}. Delegate the remaining research to the cheap explorer instead of reading more here.`,
      `Call the Task tool with subagent_type="${agentNamesForWindow(workspace)["fast-research"]}" (read-only, runs on ${verdict.model}) and a precise question: what to find, which paths or symbols, what to report (paths with line ranges, a short answer). Independent questions can be sent as parallel Task calls in the same turn. Then continue the work here using its summary.`
    ].join("\n");
  }
  if (verdict.phase === "post") {
    return [
      `CCO: ${toolName} is not allowed here after delegation. The subagent already did the work; do not re-read files or re-run its checks on ${sessionModel || "the chat model"}.`,
      "Reply to the user now by relaying the subagent's final message verbatim (it is written for them), with no cost or tier line of your own. If the subagent returned CCO-ESCALATE or CCO-VERIFY: fail, make exactly one more Task call to the next tier up; otherwise no more tool calls."
    ].join("\n");
  }
  const scores = verdict.decision?.scores
    ? `CCO-SCORES: complexity=${verdict.decision.scores.complexity} risk=${verdict.decision.scores.risk} breadth=${verdict.decision.scores.breadth} uncertainty=${verdict.decision.scores.uncertainty} latency=${verdict.decision.scores.latency}`
    : "CCO-SCORES: complexity=<0-10> risk=<0-10> breadth=<0-10> uncertainty=<0-10> latency=<0-10>";
  return [
    `CCO: ${toolName} is not allowed on ${sessionModel || "the chat model"} for this request (${verdict.reason}). Do not gather context or work around this with other tools.`,
    `Your next action must be one Task call: subagent_type="${agentForTier(verdict.tier, workspace)}" (runs on ${verdict.model}). The Task prompt must start with \`${scores}\`, then pass the user's request verbatim plus any paths or constraints they gave; the subagent reads what it needs itself. When it returns, relay its final message to the user verbatim with no further tool calls.`
  ].join("\n");
}

async function main() {
  const payload = safeJsonParse((await readStdin()).trim() || "{}");
  const workspace = workspaceFromPayload(payload);
  const paths = workspace ? workspacePaths(workspace) : null;
  try {
    const conversationId = payload.conversation_id || null;
    if (!workspace || !isEnabled(workspace).enabled) {
      emit({ permission: "allow" });
      return;
    }
    const session = loadSession(workspace, conversationId);
    if (!session || String(payload.tool_name || "") === "Task") {
      emit({ permission: "allow" });
      return;
    }
    const config = loadConfig(workspace);
    const pricing = loadPricing(paths.pricingPath);
    const runtime = readJsonSafe(paths.runtimePath);
    const models = tierModels(workspace, runtime, paths ? paths.limitsPath : null);
    if (refineSessionModel(session, payload.model)) {
      saveSession(workspace, session);
    }
    const transcriptPath = payload.transcript_path || guessTranscriptPath(workspace, conversationId);
    if (syncTurnFromTranscript(session, transcriptPath)) {
      saveSession(workspace, session);
    }
    let prompt = null;
    if (!session.decision) {
      // CLI path (no beforeSubmitPrompt): derive the decision from the latest user turn; store no text.
      prompt = userPromptFromTranscriptTurn(transcriptPath, -1) || userPromptFromTranscript(transcriptPath);
      if (prompt) {
        const override = parseOverride(prompt, config?.overrideTokens || {});
        session.decision = decideTier({ scores: heuristicScores(prompt), override, config });
        session.promptMeta = { override: /\[cco:off\]|\[cco:direct\]/i.test(prompt) ? "off" : override, questionLike: isQuestionLike(prompt), tiny: isTinyTask(prompt), chars: prompt.length };
      }
    }
    const verdict = gateDecision({ toolName: payload.tool_name, session, config, pricing, models, prompt, workspace });
    hookLog(paths, {
      event: "preToolUse:gate",
      conversation_id: conversationId,
      tool: payload.tool_name,
      action: verdict.action,
      reason: verdict.reason,
      phase: verdict.phase || null,
      tier: verdict.tier || null
    });
    if (/^(Read|Grep|Glob|ListDir|List|Search|Codebase|SemanticSearch)/i.test(String(payload.tool_name || "")) && verdict.action === "allow") {
      session.readCount = asNumber(session.readCount, 0) + 1;
      saveSession(workspace, session);
    }
    // Advise-first (default): attach the routing advice to the call and let it through; the model
    // follows the advice on its next action. Blocking is opt-in (enforcement.mode = "strict").
    // Two things are enforced even in advise mode, because advice alone measurably fails there:
    // the user's explicit [cco:<tier>] override, and quality escalations (risky work / DEEP-scored tasks on a
    // weaker chat model). Cost-driven routing and relay-only are advice unless enforcement.mode is "strict".
    const strict = String(config?.enforcement?.mode || "advise") === "strict";
    const mustEnforce = /^(quality_|override_)/.test(String(verdict.reason || ""));
    if (verdict.action === "deny" && !strict && !mustEnforce) {
      const adviseKey = `${verdict.reason}:${verdict.phase || ""}`;
      const already = Array.isArray(session.advised) && session.advised.includes(adviseKey);
      if (verdict.reason === "read_budget_use_explore") {
        session.readNudged = true;
      }
      session.advised = [...(session.advised || []), adviseKey].slice(-10);
      saveSession(workspace, session);
      hookLog(paths, { event: "preToolUse:gate", conversation_id: conversationId, tool: payload.tool_name, action: "advise", reason: verdict.reason, phase: verdict.phase || null, tier: verdict.tier || null });
      if (already) {
        emit({ permission: "allow" });
        return;
      }
      const message = denyMessage({ toolName: payload.tool_name, verdict, sessionModel: session.model, workspace }).replace(/^CCO: [^\n]*?(is not allowed|blocked)[^\n]*\n?/m, "");
      emit({ permission: "allow", agent_message: `CCO (advice, this call is allowed): ${message}` });
      return;
    }
    if (verdict.action === "deny") {
      if (verdict.reason === "read_budget_use_explore") {
        session.readNudged = true;
      } else {
        session.denials = asNumber(session.denials, 0) + 1;
      }
      session.lastDenial = { ts: new Date().toISOString(), tool: payload.tool_name, reason: verdict.reason, tier: verdict.tier, phase: verdict.phase };
      saveSession(workspace, session);
      const message = denyMessage({ toolName: payload.tool_name, verdict, sessionModel: session.model, workspace });
      const userMessage =
        verdict.reason === "read_budget_use_explore"
          ? `Research moves to ${modelLabel(verdict.model, pricing)}; ${modelLabel(session.model, pricing)} keeps the decisions and edits.`
          : verdict.phase === "post"
          ? "Relaying the subagent's result."
          : String(verdict.reason).startsWith("override_")
          ? `Routing to ${tierLabel(verdict.tier)} (${modelLabel(verdict.model, pricing)}) as requested.`
          : String(verdict.reason).startsWith("quality_")
          ? `Risky or complex change: routing to ${tierLabel(verdict.tier)} (${modelLabel(verdict.model, pricing)}).`
          : `Routing to ${tierLabel(verdict.tier)} (${modelLabel(verdict.model, pricing)}).`;
      emit({ permission: "deny", agent_message: message, user_message: userMessage });
      return;
    }
    if (verdict.reason === "escape_hatch_after_denials" || verdict.reason === "no_savings_expected") {
      session.directWork = asNumber(session.directWork, 0) + 1;
      saveSession(workspace, session);
    }
    // The model ignored the delegation reminders and the escape hatch opened: the work stays in this chat.
    // Say so once, with an honest footer (models otherwise invent one that names the tier model they never used).
    if (verdict.reason === "escape_hatch_after_denials" && !session.footerSent) {
      session.footerSent = true;
      saveSession(workspace, session);
      const model = modelLabel(session.model, pricing);
      emit({
        permission: "allow",
        agent_message: `CCO: no tier delegation was made; this work runs in this chat on ${session.model || "the chat model"}. Do not claim another model and do not add a Cost Optimizer line.`,
        user_message: `Working in chat on ${model}.`
      });
      return;
    }
    emit({ permission: "allow" });
  } catch (error) {
    hookLog(paths, { event: "preToolUse:gate", error: String(error?.message || error) });
    emit({ permission: "allow" });
  }
}

if (process.env.CCO_HOOK_MAIN === "cco-tool-gate.mjs") {
  main().catch(() => emit({ permission: "allow" }));
}
